import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from 'react-router-dom';

// --- NAVBAR: Simple o Nqiya ---
const Navbar = ({ cartCount }) => (
  <nav className="bg-white/80 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100">
    <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">

      {/* LOGO Simple */}
      <Link to="/" className="flex items-center space-x-3 group">
        <div className="bg-orange-500 p-2 rounded-full transform group-hover:scale-110 transition shadow-sm">
          <svg width="20" height="20" viewBox="0 0 512 512" fill="white" xmlns="http://www.w3.org/2000/svg">
            <path d="M416 0C380.7 0 352 28.7 352 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80zM128 0V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H80V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H16V192c0 53 43 96 96 96v192c0 17.7 14.3 32 32 32s32-14.3 32-32V288c53 0 96-43 96-96V0H224V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H160V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H128z" />
          </svg>
        </div>
        <span className="font-bold text-xl tracking-tighter text-gray-800">Fast<span className="text-orange-500">Délice</span></span>
      </Link>

      <div className="hidden md:flex space-x-8 text-[11px] font-bold uppercase tracking-widest text-gray-500">
        <Link to="/" className="hover:text-orange-500 transition">Accueil</Link>
        <Link to="/menu" className="hover:text-orange-500 transition">Menu</Link>
        <Link to="/about" className="hover:text-orange-500 transition">À Propos</Link>
      </div>

      <div className="flex items-center space-x-5">
        <Link to="/panier" className="relative p-2 text-gray-700">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
          </svg>
          <span className="absolute top-0 right-0 bg-orange-500 text-white text-[9px] font-bold rounded-full h-4 w-4 flex items-center justify-center">{cartCount}</span>
        </Link>
        <Link to="/login" className="bg-gray-900 text-white px-5 py-2.5 rounded-full text-xs font-bold uppercase tracking-widest hover:bg-orange-500 transition shadow-sm">Login</Link>
      </div>
    </div>
  </nav>
);

// --- LAYOUT: Background hsn (Less Overlay) ---
const PageLayout = ({ children, title }) => (
  <div className="relative min-h-screen font-sans">
    <div className="fixed inset-0 z-0">
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="pizza" />
      <div className="absolute inset-0 bg-white/70 backdrop-blur-[1px]"></div> {/* Rejje3nah f l-khfif bach i-ban nqi */}
    </div>
    <div className="relative z-10 max-w-6xl mx-auto px-6 py-16">
      {title && <h2 className="text-4xl md:text-5xl font-light text-gray-900 text-center mb-12 uppercase tracking-tighter italic">{title}</h2>}
      {children}
    </div>
  </div>
);

// --- HOME PAGE: Minimalist ---
const Home = () => (
  <PageLayout>
    <div className="text-center py-20">
      <h1 className="text-6xl md:text-8xl font-black text-gray-900 mb-6 tracking-tighter">Fast<span className="text-orange-500">Délice</span></h1>
