// --- MENU: Modern Card ---
const Menu = ({ categories, addToCart }) => {
  const [searchTerm, setSearchTerm] = useState("");
  const filteredDishes = categories.flatMap(c => c.dishes).filter(d => d.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <PageLayout title="La Carte">
      <div className="max-w-md mx-auto mb-16 relative">
        <input type="text" placeholder="Rechercher..." className="w-full px-6 py-4 rounded-full border border-gray-200 outline-none focus:border-orange-500 transition bg-white/80" onChange={(e) => setSearchTerm(e.target.value)} />
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        {filteredDishes.map(item => (
          <div key={item.id} className="bg-white rounded-3xl p-6 shadow-sm hover:shadow-xl transition group">
            <div className="h-40 bg-gray-50 rounded-2xl flex items-center justify-center text-5xl mb-6 group-hover:scale-105 transition italic">🍕</div>
            <h3 className="text-xl font-bold text-gray-900 mb-2">{item.name}</h3>
            <div className="flex justify-between items-center mt-6">
              <span className="font-bold text-orange-500">{item.price} DH</span>
              <button onClick={() => addToCart(item)} className="bg-gray-100 text-gray-800 p-3 rounded-xl hover:bg-orange-500 hover:text-white transition">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
              </button>
            </div>
          </div>
        ))}
      </div>
    </PageLayout>
  );
};

// --- LOGIN: Simple Form ---
const Login = () => (
  <PageLayout title="Connexion">
    <div className="max-w-sm mx-auto bg-white p-10 rounded-[2rem] shadow-sm">
      <form className="space-y-6">
        <input type="email" placeholder="Email" className="w-full border-b border-gray-200 py-3 outline-none focus:border-orange-500" />
        <input type="password" placeholder="Mot de passe" className="w-full border-b border-gray-200 py-3 outline-none focus:border-orange-500" />
        <button className="w-full bg-gray-900 text-white py-4 rounded-full font-bold uppercase text-[10px] tracking-widest hover:bg-orange-500 transition">Entrer</button>
      </form>
    </div>
  </PageLayout>
);

// --- APP ---
export default function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/').then(res => setCategories(res.data)).catch(e => console.log(e));
  }, []);

  return (
    <Router>
      <Navbar cartCount={cart.length} />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/menu" element={<Menu categories={categories} addToCart={(i) => setCart([...cart, i])} />} />
        <Route path="/login" element={<Login />} />
      </Routes>
    </Router>
  );
}
